#include "../build_config.h"
// Crusaders Mainframe — the device half of the API contract, minus the socket.
//
// WHAT AUTHENTICATION IS NOW
// --------------------------
// One static per-tenant key in an `Authorization: Bearer <key>` header, and the
// box's MAC in every request body. That is the whole of it. There is no
// timestamp, no nonce-for-auth, no canonical string, no HMAC and no clock,
// because there is one club with one box and the person who flashes it is the
// person who holds the key. An unknown or missing key is a plain 401.
//
// The key is compiled in from src/common/secrets.h, so a rotation is a reflash.
// It is a real secret rather than a formality: the club's backend is reachable
// from the internet through the Cloudflare tunnel — that is how members book and
// how the admin works remotely — so `/api/v1/device/*` is reachable too even
// though the box itself never leaves the club LAN.
//
// WHAT WAS HERE BEFORE, AND WHY IT IS NOT
// ---------------------------------------
// HMAC request signing over a canonical string, a nonce per request, a Unix
// clock held as an offset over `millis()`, `probe()` — the zero-timestamp
// request whose 401 seeded that clock — `server_unix` parsing out of every
// response body, a skew tolerance pinned against the server's, and two strike
// counters (ClockCorrected, Reprovision) deciding when a 401 meant the
// credential was dead. Every one of those existed to make signing survive a box
// with no RTC. With signing gone they were machinery guarding nothing, and each
// had a failure mode that bricked a working board: a signed timestamp that
// wrapped at day 49.7, a replayed OFFER that rewound the clock, a 401 read as a
// revoked key.
//
// WHY A 401 IS A RETRY AND NOT A DROP
// -----------------------------------
// react() is what the event drain asks before it releases an event. A 401 now
// means one thing only — the compiled-in key is not the tenant's — and that is
// true of EVERY request, not of the event at the head of the queue. Dropping on
// 401 would empty the queue of a whole evening's attendance while somebody found
// a laptop; keeping it costs nothing but a stalled drain, and the fix is a
// reflash. A 4xx that is genuinely about the request is still dropped, because
// retrying it forever pins every later event behind one the server will never
// take.
//
// WHAT THIS FILE STILL OWNS
// -------------------------
// The header name, the bearer rendering, and the status→reaction mapping. All
// three are the kind of thing that is wrong in a way no compiler catches and
// that costs a trip to the club, so they live where `pio test -e native` drives
// them rather than in the composition root.
//
// No Arduino headers, no heap, no String. Compiles for AVR, Xtensa and the host.

#ifndef CRUSADERS_DEVAPI_DEVICECLIENT_H
#define CRUSADERS_DEVAPI_DEVICECLIENT_H

#include <stddef.h>
#include <stdint.h>

namespace devapi {

/// The one authentication header, matching the server's device auth scheme.
/// A constant rather than a literal at the call site: a correct key under the
/// wrong header name is a 401 nobody can explain.
inline constexpr char kHeaderAuthorization[] = "Authorization";

/// The scheme, with its trailing space. `Bearer` capitalised exactly as the
/// server's parser expects it.
inline constexpr char kBearerPrefix[] = "Bearer ";

/// Longest device API key the box will carry, and the buffer a rendered header
/// value needs. The tenant setting is "random, at least 32 characters,
/// URL-safe"; 128 leaves room for a club that pastes something longer without
/// the box silently sending half of it.
inline constexpr size_t kMaxApiKeyLen = 128U;
inline constexpr size_t kAuthorizationBufSize = sizeof(kBearerPrefix) + kMaxApiKeyLen;

/// The MAC that names this box, as 12 lowercase hex characters with no
/// separators, plus a terminator. It goes in the BODY of every request that
/// needs a device, never in a header — the server auto-registers an unknown one
/// against the key's tenant.
inline constexpr size_t kMacHexLen = 12U;

/// Renders `Bearer <apiKey>` into `out`. Returns the length written, or 0 —
/// with `out` empty — when the key is missing, empty, or too long for the
/// buffer. Refused rather than truncated: half a key is a 401 that reads
/// exactly like the wrong key, and the box cannot tell the difference.
size_t renderAuthorization(char* out, size_t cap, const char* apiKey);

/// How the box should react to a response. The mapping is here rather than at
/// the call site because "what does a 401 mean" is a policy question with a
/// wrong answer that empties the event queue.
enum class Reaction : uint8_t {
  /// Accepted. Any queued events covered by it may be released.
  Accepted = 0U,
  /// Refused for a reason retrying will not fix — a malformed body, an unknown
  /// court. Retrying forever would pin the queue behind an event that can never
  /// be accepted, so it is dropped and counted.
  Rejected = 1U,
  /// Transient, or not about this request at all: no route, a 5xx, a timeout, a
  /// rate limit, or a 401 that says the compiled-in key is wrong. Keep the
  /// event and back off.
  Retry = 2U,
};

/// Interprets a response status. `0` means the request never completed.
Reaction react(uint16_t status);

/// Bytes for the walk-up purchase nonce. Injected so a test can produce a
/// SPECIFIC request and compare it against a fixture — code that reached for a
/// platform RNG could only ever be tested against itself.
///
/// This survived the removal of request signing on purpose: the walk-up nonce is
/// an IDEMPOTENCY key, not an authentication one. A purchase whose response was
/// lost looks, from the box, exactly like one that never landed, and re-sending
/// it without a nonce is a second booking and a second charge.
class IEntropySource {
public:
  virtual ~IEntropySource() = default;
  virtual uint8_t nextByte() = 0;
};

} // namespace devapi

#endif // CRUSADERS_DEVAPI_DEVICECLIENT_H
